import type { Partner } from '../../src/types/partner';

/** Синтетический набор без персональных данных реальных людей */
export function createSyntheticPartners(): Partner[] {
  const base = (partial: Partial<Partner> & { partnerNumber: string }): Partner => ({
    fullName: null,
    registrationCatalog: null,
    phone: null,
    email: null,
    sponsorNumber: null,
    inviterNumber: null,
    fileLevel: null,
    personalBB: null,
    beautyBB: null,
    groupBB: null,
    percent: null,
    maxPercent: null,
    salesVolume: null,
    groupSalesVolume: null,
    wellnessBB: null,
    novAgeBB: null,
    programPlus: null,
    teamBonus: null,
    teamBonusPlus: null,
    recommendBonus: null,
    extraBonuses: null,
    overdueDebt: null,
    inactiveCatalogs: null,
    status: null,
    rawFields: {},
    ...partial,
  });

  return [
    base({
      partnerNumber: '100',
      fullName: 'Root Partner',
      sponsorNumber: '1',
      inviterNumber: '1',
      personalBB: 150,
      groupBB: 500,
      fileLevel: 0,
    }),
    base({
      partnerNumber: '200',
      fullName: 'Alpha One',
      sponsorNumber: '100',
      inviterNumber: '100',
      personalBB: 40,
      groupBB: 200,
      fileLevel: 1,
    }),
    base({
      partnerNumber: '201',
      fullName: 'Beta Two',
      sponsorNumber: '100',
      inviterNumber: '100',
      personalBB: 0,
      groupBB: 50,
      fileLevel: 1,
    }),
    base({
      partnerNumber: '300',
      fullName: 'Gamma Three',
      sponsorNumber: '200',
      inviterNumber: '200',
      personalBB: 80,
      groupBB: 80,
      fileLevel: 2,
    }),
    base({
      partnerNumber: '301',
      fullName: 'Delta Four',
      sponsorNumber: '200',
      inviterNumber: '100',
      personalBB: null,
      groupBB: null,
      fileLevel: 2,
    }),
  ];
}

